cd /dayjs && cat > test/scratch.test.js <<'EOF'
import moment from 'moment'
import dayjs from '../src'
import weekYear from '../src/plugin/weekYear'
import weekOfYear from '../src/plugin/weekOfYear'
import '../src/locale/en-gb'
import '../src/locale/zh-cn'
dayjs.extend(weekYear)
dayjs.extend(weekOfYear)
it('scratch', () => {
  const dates = ['2018-12-30', '2018-12-31', '2019-01-01', '2019-01-02', '2019-01-03', '2019-01-04', '2019-01-05', '2019-01-06', '2016-01-01', '2016-01-03', '2016-01-04', '2019-12-29', '2019-12-30', '2019-12-31', '2020-01-01']
  ;['en-gb', 'zh-cn', 'en'].forEach((loc) => {
    dayjs.locale(loc)
    moment.locale(loc)
    dates.forEach((d) => {
      const dj = dayjs(d)
      const m = moment(d)
      const djw = `${dj.weekYear()}/${dj.week()}`
      const mw = `${m.weekYear()}/${m.week()}`
      if (djw !== mw) console.log('MISMATCH', loc, d, 'dayjs', djw, 'moment', mw)
    })
  })
})
EOF
npx jest test/scratch.test.js --coverage=false 2>&1 | head -40

cd /dayjs && cat > test/scratch.test.js <<'EOF'
import moment from 'moment'
import dayjs from '../src'
import advancedFormat from '../src/plugin/advancedFormat'
import '../src/locale/nl'
dayjs.extend(advancedFormat)
it('scratch', () => {
  dayjs.locale('nl')
  moment.locale('nl')
  for (let i = 1; i <= 31; i += 1) {
    const d = `2018-05-${String(i).padStart(2, '0')}`
    const a = dayjs(d).format('Do')
    const b = moment(d).format('Do')
    if (a !== b) console.log('MISMATCH', i, JSON.stringify(a), JSON.stringify(b))
  }
})
EOF
npx jest test/scratch.test.js --coverage=false 2>&1 | head -50
